/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        items: [cc.Node],
        jackpot_result: cc.Node,
        jptanchuang: sp.Skeleton,
        winCoin: cc.Label,
        btn_collect: cc.Node,
        kuang: sp.Skeleton,
        kuloushouzhi: sp.Skeleton,
        black_bg: cc.Node,
        press_node: sp.Skeleton,

        _startMove: false,
        _newSpeed: 1,
        _newMaxSpeed: 20,
        _newMinSpeed: 1,
        _newSpeedOffset: 0.25,
        _count: 6,      // 需要转几轮
        _needStop: false,
        _bottomPosY: 0,
        _backMove: false,
        _resultItem: null,        // 结果索引 从1开始
        _successCallback: null,
        _hasPressed: true,

        _wheelResult: null,
    },

    onLoad() {
        this.press_node.node.on(cc.Node.EventType.TOUCH_END, () => {
            if (this._hasPressed) {
                return;
            }
            this._hasPressed = true;
            this.press_node.node.stopAllActions();

            cc.tween(this.black_bg)
                .to(0.2, {opacity: 0})
                .start();

            this.press_node.clearTracks();
            this.press_node.setToSetupPose();
            this.press_node.setAnimation(0, "animation3", false);
            this.press_node.setCompleteListener((track)=>{
                let name = track.animation ? track.animation.name : "";
                if (name === "animation3") {
                    this._startMove = true;

                    cc.vv.AudioManager.playEff("games/VampireCount/", "jp_spin", true);

                    this.press_node.active = false;

                    this.kuloushouzhi.node.active = true;
                    this.kuloushouzhi.setAnimation(0, "animation", false);
                    this.kuloushouzhi.addAnimation(0, "animation2", true);
                }
            });
        });

        this._bottomPosY = this.items[9].y - this.items[9].height;
    },

    update(dt) {
        if (this._startMove) {
            if (!this._needStop) {
                this._newSpeed += this._newSpeedOffset;
                if (this._newSpeed >= this._newMaxSpeed) {
                    this._newSpeed = this._newMaxSpeed;
                }
            } else {
                this._newSpeed -= this._newSpeedOffset;
                if (this._newSpeed <= this._newMinSpeed) {
                    this._newSpeed = this._newMinSpeed;
                }
            }

            if (this._count === 0 && this._resultItem.y <= 5 * this._resultItem.height) {
                this._needStop = true;
            }

            if (this._needStop && this._resultItem.y < 0) {
                this._startMove = false;
                this._backMove = true;
            }

            for (let item of this.items) {
                if (item.y <= this._bottomPosY) {
                    item.y += this.items.length * item.height;
                    if (item === this._resultItem) {
                        this._count--;
                        if (this._count <= 0) {
                            this._count = 0;
                        }
                    }
                }

                item.y -= this._newSpeed;
            }
        }

        if (this._backMove) {
            for (let item of this.items) {
                item.y += this._newMinSpeed;
            }

            if (this._resultItem.y > -1 && this._resultItem.y < 1) {
                this._backMove = false;
                this._moveEnd();
            }
        }
    },

    _moveEnd() {
        cc.vv.AudioManager.playEff("games/VampireCount/", "jp_stop", true);
        this.kuang.node.active = true;
        this.kuang.clearTracks();
        this.kuang.setToSetupPose();
        this.kuang.setAnimation(0, "animation1", false);
        this.kuang.setCompleteListener(async (track)=>{
            let name = track.animation ? track.animation.name : "";
            if (name === "animation1") {
                this.kuang.clearTracks();
                this.kuang.setToSetupPose();
                this.kuang.setAnimation(0, "animation2", true);

                let prizePool = cc.find("LMSlots_PrizePool_1", this.node.parent)
                    .getComponent("VampireCount_PrizePool")
                    ._GetPoolNodeByType(this._wheelResult.id - 1);
                if (prizePool) {
                    let jpzhongjiang = cc.find("unlock/jpzhongjiang", prizePool);
                    if (jpzhongjiang) {
                        cc.vv.AudioManager.playEff("games/VampireCount/", "jp_multi", true);
                        jpzhongjiang.active = true;
                        this.scheduleOnce(()=>{
                            jpzhongjiang.active = false;
                        }, 1);
                    }
                }

                // cc.tween(this.kuang.node)
                //     .to(0.2, {scale: 1.2})
                //     .to(0.2, {scale: 1})
                //     .to(0.2, {scale: 1.1})
                //     .to(0.2, {scale: 1})
                //     .start();
                //
                // cc.tween(this._resultItem)
                //     .to(0.2, {scale: 1.2})
                //     .to(0.2, {scale: 1})
                //     .to(0.2, {scale: 1.1})
                //     .to(0.2, {scale: 1})
                //     .start();

                await cc.vv.gameData.awaitTime(1);

                // 弹结算
                let animationIndex = [4, 3, 2, 1];
                let sound = ["wheel_mini", "wheel_minor", "wheel_major", "wheel_grand"];
                cc.vv.AudioManager.playEff("games/VampireCount/", sound[this._wheelResult.id - 1], true);
                this.jackpot_result.active = true;
                this.jptanchuang.clearTracks();
                this.jptanchuang.setToSetupPose();
                this.jptanchuang.setAnimation(0, "animation" + animationIndex[this._wheelResult.id - 1], false);
                this.jptanchuang.setCompleteListener((track)=>{
                    let name = track.animation ? track.animation.name : "";
                    if (name === "animation" + animationIndex[this._wheelResult.id - 1]) {
                        this.jptanchuang.clearTracks();
                        this.jptanchuang.setToSetupPose();
                        this.jptanchuang.setAnimation(0, "animation" + animationIndex[this._wheelResult.id - 1] + "_1", true);
                    }
                });
                this.winCoin.string = "";
                this.btn_collect.scale = 0;

                await cc.vv.gameData.awaitTime(1);
                Global.doRoallNumEff(this.winCoin.node, 0, this._wheelResult.value, 3, null, null, 0, true, false);
                cc.tween(this.btn_collect)
                    .to(0.5, {scale: 1}, {easing: "backOut"})
                    .start();

                await cc.vv.gameData.awaitTime(0.5);
                this.btn_collect.off("click");

                let func = ()=> {
                    this.btn_collect.off("click");
                    cc.vv.AudioManager.playEff("games/VampireCount/", "click", true);
                    cc.tween(this.btn_collect)
                        .to(0.5, {scale: 0}, {easing: "backIn"})
                        .start();

                    this.jptanchuang.clearTracks();
                    this.jptanchuang.setToSetupPose();
                    this.jptanchuang.setAnimation(0, "animation" + animationIndex[this._wheelResult.id - 1] + "_2", false);

                    this.jptanchuang.setCompleteListener((track) => {
                        let name = track.animation ? track.animation.name : "";
                        if (name === "animation" + animationIndex[this._wheelResult.id - 1] + "_2") {
                            this.jackpot_result.active = false;
                            this.kuloushouzhi.node.active = false;
                            if (this._successCallback) {
                                this._successCallback();
                            }
                        }
                    });
                };

                cc.vv.gameData.checkAutoPlay(this.btn_collect, func);

                this.btn_collect.on("click", ()=>{
                    this.btn_collect.stopAllActions();
                    func();
                });
            }
        });
    },

    async enterWheelGame(successCallback, result) {
        this._wheelResult = result;
        this._resultItem = cc.find("wheel_mask/index_" + result.idx, this.node);
        this.node.active = true;
        this._successCallback = successCallback;

        this.kuang.node.active = false;

        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("wheel_bgm");

        cc.vv.AudioManager.playEff("games/VampireCount/", "wheel_start_show", true);

        this.reset();

        this.black_bg.opacity = 200;

        this.press_node.node.active = true;
        this.press_node.clearTracks();
        this.press_node.setToSetupPose();
        this.press_node.setAnimation(0, "animation", false);
        this.press_node.setCompleteListener((track)=>{
            let name = track.animation ? track.animation.name : "";
            if (name === "animation") {
                this.press_node.clearTracks();
                this.press_node.setToSetupPose();
                this.press_node.setAnimation(0, "animation2", true);
            }
        });

        cc.vv.gameData.checkAutoPlay(this.press_node.node, ()=>{
            if (this._hasPressed) {
                return;
            }
            this._hasPressed = true;

            cc.tween(this.black_bg)
                .to(0.2, {opacity: 0})
                .start();

            this.press_node.clearTracks();
            this.press_node.setToSetupPose();
            this.press_node.setAnimation(0, "animation3", false);
            this.press_node.setCompleteListener((track)=>{
                let name = track.animation ? track.animation.name : "";
                if (name === "animation3") {
                    this._startMove = true;

                    cc.vv.AudioManager.playEff("games/VampireCount/", "jp_spin", true);

                    this.press_node.active = false;

                    this.kuloushouzhi.node.active = true;
                    this.kuloushouzhi.setAnimation(0, "animation", false);
                    this.kuloushouzhi.addAnimation(0, "animation2", true);
                }
            });
        });
    },

    reset() {
        // 最下边的位置
        this._startMove = false;
        this._newSpeed = 1;
        this._needStop = false;
        this._count = 6;
        this._hasPressed = false;
        this._backMove = false;
    },
});