/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        role: cc.Node,
        points: [cc.Node],
        map: cc.Node,
        start_node: cc.Node,
        btn_back: cc.Node,
    },

    initMap(mapInfo) {
        this.node.active = true;
        this.map.y = cc.winSize.height;
        let cfg = cc.vv.gameData.getGameCfg();
        // 基础
        for (let i = 0; i < cfg.MapConfig.length; i++) {
            let pointCfg = cfg.MapConfig[i];
            let point = this.points[i];
            let spine = point.getChildByName("spine").getComponent(sp.Skeleton);
            if (pointCfg.type === cfg.MapType.PickBooster) {
                if (i < mapInfo.currId) {
                    // 已解锁
                    spine.clearTracks();
                    spine.setToSetupPose();
                    spine.setAnimation(0, "animation4", true);
                } else {
                    // 未解锁
                    spine.clearTracks();
                    spine.setToSetupPose();
                    spine.setAnimation(0, "animation3", true);
                }
            } else if (pointCfg.type === cfg.MapType.SuperFreeGame) {
                let common = point.getChildByName("common");
                let finish = point.getChildByName("finish");
                common.active = i >= mapInfo.currId;
                finish.active = i < mapInfo.currId;

                if (i < mapInfo.currId) {
                    spine.setAnimation(0, "animation" + pointCfg.index + "_3", true);
                } else {
                    spine.setAnimation(0, "animation" + pointCfg.index + "_2", true);
                }

                for (let i = 1; i < 6; i++) {
                    let tips = common.getChildByName("tips_" + i);
                    if (tips) {
                        tips.getChildByName("no").active = false;
                        tips.getChildByName("yes").active = false;
                    }
                }
            }
        }

        // 下一个大关卡的信息
        let nextFreeGameIndex = mapInfo.currId >= 1 ? cfg.MapConfig[mapInfo.currId - 1].nextSlotsId - 1 : cfg.MapConfig[0].nextSlotsId - 1;
        let nextFreeGameCfg = cfg.MapConfig[nextFreeGameIndex];
        let nextFreeGamePoint = this.points[nextFreeGameIndex];
        if (nextFreeGamePoint) {
            let common = nextFreeGamePoint.getChildByName("common");
            if (common) {
                for (let i = 1; i < 6; i++) {
                    let tips = common.getChildByName("tips_" + i);
                    if (tips) {
                        tips.getChildByName("no").active = false;
                        tips.getChildByName("yes").active = mapInfo.nextUnlockBoosters.indexOf(i) !== -1;
                    }
                }

                common.getChildByName("num").getComponent(cc.Label).string = mapInfo.nextUnlockBoosters.length;
            }
        }

        let startPoint = mapInfo.currId <= 0 ? this.start_node : this.points[mapInfo.currId - 1];
        this.role.active = true;
        this.role.position = startPoint.position;
    },

    openMap(showBtn) {
        this.node.active = true;
        this.map.y = cc.winSize.height;
        cc.vv.AudioManager.playEff("games/VampireCount/", "map_open", true);
        cc.tween(this.map)
            .to(0.5, {y : 0})
            .start();
        if (showBtn) {
            this.btn_back.active = true;
            this.btn_back.scale = 0;
            cc.tween(this.btn_back)
                .delay(0.6)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            this.btn_back.on("click", ()=>{
                this.btn_back.off("click");
                cc.vv.AudioManager.playEff("games/VampireCount/", "map_close", true);
                cc.tween(this.btn_back)
                    .to(0.2, {scale: 0})
                    .start();

                cc.tween(this.map)
                    .to(0.5, {y : cc.winSize.height})
                    .call(()=>{
                        cc.vv.gameData.GetSlotsScript().CanDoNextRound();
                        this.node.active = false;
                    })
                    .start();
            });
        }
    },

    async showMap(mapInfo) {
        this.node.active = true;
        let cfg = cc.vv.gameData.getGameCfg();
        this.initMap(mapInfo);

        let pointCfg = cfg.MapConfig[mapInfo.currId - 1];
        let point = this.points[mapInfo.currId - 1];
        let spine = point.getChildByName("spine").getComponent(sp.Skeleton);

        if (pointCfg.type === cfg.MapType.PickBooster) {
            // 未解锁
            spine.clearTracks();
            spine.setToSetupPose();
            spine.setAnimation(0, "animation3", true);
        } else if (pointCfg.type === cfg.MapType.SuperFreeGame) {
            let common = point.getChildByName("common");
            let finish = point.getChildByName("finish");
            common.active = true;
            finish.active = false;

            spine.setAnimation(0, "animation" + pointCfg.index + "_2", true);

            for (let i = 1; i < 6; i++) {
                let tips = common.getChildByName("tips_" + i);
                if (tips) {
                    tips.getChildByName("no").active = mapInfo.nextUnlockBoosters.indexOf(i) === -1;
                    tips.getChildByName("yes").active = mapInfo.nextUnlockBoosters.indexOf(i) !== -1;
                }
            }
        }

        this.openMap(false);

        await cc.vv.gameData.awaitTime(0.5);

        let position = point.convertToWorldSpaceAR(cc.v2(0, 0));
        let percentY = position.y / cc.winSize.height - 0.15;
        if (percentY < 0) {
            percentY = 0;
        } else if (percentY > 1) {
            percentY = 1;
        }
        this.map.getComponent(cc.ScrollView).scrollToPercentVertical(percentY);

        let startPoint = mapInfo.currId - 1 <= 0 ? this.start_node : this.points[mapInfo.currId - 2];
        let endPoint = this.points[mapInfo.currId - 1];
        this.role.active = true;
        this.role.position = startPoint.position;
        cc.vv.AudioManager.playEff("games/VampireCount/", "map_move", true);
        this.role.getComponent(sp.Skeleton).setAnimation(0, "animation2", false);
        this.role.getComponent(sp.Skeleton).setCompleteListener(()=>{
            this.role.getComponent(sp.Skeleton).setCompleteListener(null);
            this.role.active = false;
        });
        cc.tween(this.role)
            .delay(0.5)
            .then(cc.jumpTo(1, endPoint.position.x, endPoint.position.y, 50, 1))
            .start();

        await cc.vv.gameData.awaitTime(2);

        let endPointCfg = cfg.MapConfig[mapInfo.currId - 1];
        if (endPointCfg.type === cfg.MapType.PickBooster) {
            // 进入选择小游戏
            let spine = endPoint.getChildByName("spine").getComponent(sp.Skeleton);
            spine.setAnimation(0, "animation1", false);
            spine.addAnimation(0, "animation2", true);

            await cc.vv.gameData.awaitTime(1);

            // 切屏进pick game
            this.cutScenePick();

            await cc.vv.gameData.awaitTime(1.8);

            let script = cc.find("pick_game", this.node.parent).getComponent("VampireCount_PickGame");
            await script.enterPickGame(
                endPointCfg.index,
                endPointCfg.pickCnt,
                cc.vv.gameData.getGameInfo() ?
                    cc.vv.gameData.getGameInfo().pickBoosterGame : cc.vv.gameData.getDeskInfo().pickBoosterGame
            );

            this.cutScenePick();

            await cc.vv.gameData.awaitTime(1.8);
            cc.find("pick_game", this.node.parent).active = false;

            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();
            
            let result = script.getResult();
            let num = 0;
            for (let choiceItem of result.pickBoosterGame.choiceItems) {
                if (choiceItem.type !== cfg.MapBoostType.Coin) {
                    num++;
                }
            }
            if (num === 0) {
                this.map.getComponent(cc.ScrollView).scrollToPercentVertical(percentY);
                this.map.y = cc.winSize.height;
            } else {
                await cc.vv.gameData.awaitTime(0.5);

                let nextFreeGamePoint = this.points[endPointCfg.nextSlotsId - 1];
                cc.find("common/num", nextFreeGamePoint).getComponent(cc.Label).string = num;
                for (let choiceItem of result.pickBoosterGame.choiceItems) {
                    if (choiceItem.type !== cfg.MapBoostType.Coin) {
                        let boosetervx = cc.instantiate(cc.find("boostervx", this.node));
                        boosetervx.active = true;
                        boosetervx.parent = this.node;
                        let position = nextFreeGamePoint.getChildByName("common").convertToWorldSpaceAR(cc.v2(0, 0));
                        position = this.node.convertToNodeSpaceAR(position);
                        boosetervx.position = position;
                        boosetervx.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
                        boosetervx.getComponent(sp.Skeleton).addAnimation(0, "animation3", true);

                        await cc.vv.gameData.awaitTime(1);
                        let endPos = cc.find("common/tips_" + choiceItem.type + "/yes", nextFreeGamePoint).convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = this.node.convertToNodeSpaceAR(endPos);
                        cc.tween(boosetervx)
                            .to(0.3, {position: endPos})
                            .call(()=>{
                                cc.find("common/tips_" + choiceItem.type + "/yes", nextFreeGamePoint).active = true;
                                boosetervx.x = position.x;
                                boosetervx.getComponent(sp.Skeleton).setAnimation(0, "animation5", false);
                                boosetervx.getComponent(sp.Skeleton).setCompleteListener(()=>{
                                    boosetervx.removeFromParent();
                                })
                            })
                            .start();
                        await cc.vv.gameData.awaitTime(0.2);
                    }
                }

                for (let i = endPointCfg.nextSlotsId - 1; i < this.points.length; i++) {
                    let point = this.points[i];
                    let pointCfg = cfg.MapConfig[i];
                    if (pointCfg.type === cfg.MapType.SuperFreeGame) {
                        let spine = point.getChildByName("spine").getComponent(sp.Skeleton);
                        spine.setAnimation(0, "animation" + pointCfg.index + "_4", true);
                    }
                }

                await cc.vv.gameData.awaitTime(2);
                cc.vv.AudioManager.playEff("games/VampireCount/", "map_close", true);
                cc.tween(this.map)
                    .to(0.5, {y: cc.winSize.height})
                    .call(()=>{
                        this.map.getComponent(cc.ScrollView).scrollToPercentVertical(percentY);
                    })
                    .start();

                await cc.vv.gameData.awaitTime(0.5);
            }
        } else if (endPointCfg.type === cfg.MapType.SuperFreeGame) {
            // 进入免费游戏
            for (let i = 0; i < cfg.MapConfig.length; i++) {
                let pointCfg = cfg.MapConfig[i];
                if (pointCfg.type === cfg.MapType.SuperFreeGame) {
                    let point = this.points[i];
                    let spine = point.getChildByName("spine").getComponent(sp.Skeleton);
                    if (i >= mapInfo.currId - 1) {
                        spine.setAnimation(0, "animation" + pointCfg.index + "_4", false);
                        if (mapInfo.currId === i + 1) {
                            cc.vv.AudioManager.playEff("games/VampireCount/", "map_node", true);
                            spine.addAnimation(0, "animation" + pointCfg.index + "_1", false);
                            spine.addAnimation(0, "animation" + pointCfg.index + "_3", true);
                        } else {
                            spine.addAnimation(0, "animation" + pointCfg.index + "_2", true);
                        }
                    }
                }
            }

            await cc.vv.gameData.awaitTime(5);
            cc.vv.AudioManager.playEff("games/VampireCount/", "map_close", true);
            cc.tween(this.map)
                .to(0.5, {y: cc.winSize.height})
                .start();

            await cc.vv.gameData.awaitTime(0.5);
        }
    },

    cutScenePick() {
        cc.vv.AudioManager.playEff("games/VampireCount/", "transition3", true);
        let pick_qieping = cc.find("pick_qieping", this.node.parent);
        pick_qieping.active = true;
        let spine = pick_qieping.getComponent(sp.Skeleton);
        spine.setToSetupPose();
        spine.setAnimation(0, "animation", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            pick_qieping.active = false;
        })
    },
});