/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    //旋转
    StartMove:function(){
        this._super();
    },

    //列停止
    OnReelSpinEnd:function(){
        this._super();

        this.checkPumpkinMan();
    },

    playReelStop(){
        this._super();

        if (this._originResult) {
            for(let i = 0; i < this._originResult.length; i++){
                let item = this._symbols[i]
                if (item.GetShowId() === this._cfg.extraSpinId) {
                    cc.vv.AudioManager.playEff("games/VampireCount/", "extra_free", true);
                    item.playStopAnimation();
                }
            }
        }
    },
    
    checkPumpkinMan() {
        let cards = cc.vv.gameData.getGameInfo().resultCards;
        for (const symbol of this._symbols) {
            if (symbol.GetShowId() === this._cfg.pumpkinManId &&
                symbol.GetSymbolIdx() > 0 &&
                symbol.GetSymbolIdx() < cards.length / this._cfg.col - 1 &&
                cc.vv.gameData.getGameInfo().pumpkinGame) {
                cc.vv.AudioManager.playEff("games/VampireCount/", "bonus_landing", true);
                symbol.playStopAnimation();

                if (cc.vv.gameData.getGameInfo().pumpkinGame.double) {
                    let pumpkin = cc.find("pumpkin_" + (this._reelIdx + 1), this.node.parent.parent);
                    let info = cc.vv.gameData.GetSlotsScript().getPumpkinInfo()[this._reelIdx];
                    if (pumpkin) {
                        let double_spine = cc.find("double", pumpkin).getComponent(sp.Skeleton);
                        double_spine.clearTracks();
                        double_spine.setToSetupPose();
                        double_spine.setAnimation(0, "animation3", false);
                        double_spine.setCompleteListener((track)=>{
                            let name = track.animation ? track.animation.name : "";
                            if (name === "animation3") {
                                Global.doRoallNumEff(cc.find("coin", pumpkin), info.coin, info.coin * 2, 1, null, null, 1, true, true);
                                info.coin *= 2;
                            }
                        });
                    }
                }
            }
        }  
    },

    AppendSymbol:function(symbolArray,dir){
        for(let i = 0; i < symbolArray.length; i++){
            let node = cc.instantiate(this._symbolTemplete)
            node.parent = this._holderNode
            let scp = node.addComponent(this._cfg.scripts.Symbols)
            scp.SetSymbolReelIdx(this._reelIdx)
            if(dir === 1){

                let idx = -1 - i; //行号
                node.position = this.GetSymbolPosByRow(idx)

                scp.Init(idx,this._topAniNode)

                this._symbols.unshift(scp)
            }
            else if(dir === 2){
                let idx = this._symbols.length-1; //插到倒数第二个，让最后一个一直往后拍
                scp.Init(idx,this._topAniNode)
                this._symbols.splice(idx,0,scp)
            }

            scp.ShowById(symbolArray[i].id, symbolArray[i].data);
        }

        if(dir === 2){ // 顶部添加，中间会有一个默认格子
            this.ReLayOut()
        }
    },

    deleteSymbol(index) {
        let symbol = this._symbols[index];
        this._symbols.splice(index, 1);
        symbol.setAnimationToTop(false);
        symbol.ShowKuang(false);
        symbol.node.destroy();
    },

    clearLastSymbol() {
        let symbol = this._symbols[this._symbols.length - 1];
        if (symbol) {
            symbol.setAnimationToTop(false);
            symbol.ShowKuang(false);
        }
    },

    //reel变化尺寸的时候，需要设置高度的节点(y锚点都是0，这样设置长度都是y方向)
    //reel/mask ,
    //reels_bg/bg*,
    GetResizeHeightObjs:function(){
        let objs = []
        let mask = cc.find("mask",this.node)
        if(mask){
            objs.push(mask)
        }

        let bg = cc.find("reels_bg/reel_bg"+(this._reelIdx+1),this.node.parent.parent)
        if(bg){
            objs.push(bg)
        }

        if (this._reelIdx === 0) {
            let left_bg = cc.find("reels_frame/left_bg", this.node.parent.parent);
            if (left_bg) {
                objs.push(left_bg);
            }

            let right_bg = cc.find("reels_frame/right_bg", this.node.parent.parent);
            if (right_bg) {
                objs.push(right_bg);
            }

            for (let i = 1; i < 5; i++) {
                let line = cc.find("reels_frame/line_" + i, this.node.parent.parent);
                if (line) {
                    objs.push(line);
                }
            }

            let black_bg = cc.find("black_bg", this.node.parent.parent);
            if (black_bg) {
                objs.push(black_bg);
            }
        }

        return objs
    },

    //reel变化尺寸的时候，需要移动的节点
    //reels_frame/reel*/frame
    GetResizeMoveingObjs:function(){
        let objs = []

        if (this._reelIdx === 0) {
            let frameTop = cc.find("reels_frame/top_bg",this.node.parent.parent)
            if(frameTop){
                objs.push(frameTop)
            }
        }

        return objs
    },
});