/**
 * @description
 */
let BonusType = {
    Coin: 1,
    Double: 2,
    JackpotWheel: 3,
};

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    StartMove: function () {
        this._super();
        let cfg = cc.vv.gameData.getGameCfg();
        if (this._id === cfg.pumpkinManId) {
            this.node.zIndex = 1000;
        }

        if (this._id === cfg.scatterId) {
            this.node.zIndex = 500;
        }
    },

    ShowById(id, data) {
        let cfg = cc.vv.gameData.getGameCfg();
        this._super(id, data);

        if (id === cfg.bonusId && data) {
            cc.find("coin_bg/coin", this._showNode).active = data.type === BonusType.Coin;
            cc.find("coin_bg/double", this._showNode).active = data.type === BonusType.Double;
            cc.find("coin_bg/wheel", this._showNode).active = data.type === BonusType.JackpotWheel;
            cc.find("coin_bg/coin", this._showNode).opacity = 255;
            cc.find("coin_bg/double", this._showNode).opacity = 255;
            cc.find("coin_bg/wheel", this._showNode).opacity = 255;
            cc.find("coin_bg/coin", this._showNode).scale = 1;
            cc.find("coin_bg/double", this._showNode).scale = 1;
            cc.find("coin_bg/wheel", this._showNode).scale = 1;
            cc.find("coin_bg", this._showNode).opacity = 255;
            if (data.type === BonusType.Coin) {
                cc.find("coin_bg/coin", this._showNode).getComponent(cc.Label).string = Global.formatNumShort(data.coin, 0);
            }
        }
    },

    playCoinAnimation() {
        cc.find("icon", this._showNode).active = false;
        let node = cc.find("coin_bg/coin", this._showNode);
        if (this._data.type === BonusType.Double) {
            node = cc.find("coin_bg/double", this._showNode);
        } else if (this._data.type === BonusType.JackpotWheel) {
            node = cc.find("coin_bg/wheel", this._showNode);
        }

        let bg = cc.find("coin_bg", this._showNode);
        cc.tween(bg)
            .to(0.2, {opacity: 0})
            .start();

        cc.tween(node)
            .to(0.5, {opacity: 0, scale: 1.1})
            .start();
    },

    playTriggerAnimation(callback){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name !== ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].trigger_ani.name,false);
                    if (this._id === cfg.pumpkinManId) {
                        cc.vv.AudioManager.playEff("games/VampireCount/", "pumpkin_wheel", true);
                    }
                    nodeSp.setCompleteListener((track)=>{
                        let name = track.animation ? track.animation.name : "";
                        if (name === cfg.symbol[id].trigger_ani.name) {
                            if (this._id === cfg.pumpkinManId) {
                                nodeSp.clearTracks();
                                nodeSp.setToSetupPose();
                                nodeSp.setAnimation(0, "animation2", true);
                            }

                            if (this._id === cfg.scatterId || this._id === cfg.extraSpinId) {
                                nodeSp.clearTracks();
                                nodeSp.setToSetupPose();
                                nodeSp.setAnimation(0, cfg.symbol[id].idle_ani.name, true);
                            }

                            if (callback) {
                                callback(topShowNode);
                            }
                        }
                    });
                }
            }
        }
        return isPlay
    },

    //设置_symbolIdx 行序号
    SetSymbolIdx:function(idx){
        this._super(idx);
        let cfg = cc.vv.gameData.getGameCfg();
        if (this._id === cfg.pumpkinManId) {
            this.node.zIndex = 1000;
        }

        if (this._id === cfg.scatterId) {
            this.node.zIndex = 500;
        }
    },

    GetSymbolIdx() {
        return this._symbolIdx;
    },
});