/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        bg: cc.Node,
        top_bg: cc.Node,
        pick_times: sp.Skeleton,
        tips: sp.Skeleton,
        role: sp.Skeleton,
        items: [cc.Node],
        black_bg: cc.Node,

        _haveOpenReward:[],
        _canSelect: true,
        _index: 1,          // 动画索引
        _result: null,
        _successCallback: null,
        _unlockBooster: [],
    },

    onLoad () {
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameData, this);
    },

    changeBg(index, times) {
        this._index = index;
        // this.bg.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetSpriteFrameByName("theme214_pick_bg" + index);
        let atlas = cc.vv.gameData.GetAtlasByName("pick");
        this.top_bg.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme214_pick_top" + (index === 4 ? 3 : index));
        this.pick_times.setAnimation(0, "animation" + (times - 1), true);
        this.tips.setAnimation(0, "animation" + index, true);

        for (let i = 1; i < 9; i++) {
            let item = cc.find("item_" + i, this.node);
            let spine = cc.find("spine", item).getComponent(sp.Skeleton);
            spine.node.active = true;
            spine.setAnimation(0, "animation" + index + "_1", true);
            for (let j = 1; j < 7; j++) {
                let result = item.getChildByName("result_" + j);
                result.active = false;
                result.color = cc.Color.WHITE;
                for (let child of result.children) {
                    child.color = cc.Color.WHITE;
                }
            }
        }
    },

    async enterPickGame(index, times, pickBoosterGame) {
        return new Promise((success)=>{
            this._successCallback = success;
            this.node.active = true;
            this.reset();
            this.changeBg(index, times);

            for (let i = 0; i < pickBoosterGame.choiceIdxs.length; i++) {
                let index = pickBoosterGame.choiceIdxs[i];
                let item = cc.find("item_" + index, this.node);
                this.showReward(item, false, pickBoosterGame.choiceItems[i]);
                this._haveOpenReward.push(index);
            }

            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("pick_bgm");

            for (let i = 1; i < 9; i++) {
                let item = cc.find("item_" + i, this.node);
                item.off(cc.Node.EventType.TOUCH_END);
                item.on(cc.Node.EventType.TOUCH_END, ()=>{
                    item.stopAllActions();
                    this.onClickItem(i);
                });
            }
            this.setAutoPlay()
        });

    },

    onClickItem(i){
        let item = cc.find("item_" + i, this.node);
        item.off(cc.Node.EventType.TOUCH_END);
        if (!this._canSelect) {
            return;
        }
        if(this._haveOpenReward.indexOf(i) >= 0){
            return;
        }

        for (let i = 1; i < 9; i++) {
            let item = cc.find("item_" + i, this.node);
            item.stopAllActions();
        }

        this._canSelect = false;
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.uid = Global.playerData.uid;
        req.gameid = cc.vv.gameData._gameId;
        req.data = {};
        req.data.rtype = 1;
        req.data.choiceId = i;
        cc.vv.NetManager.send(req);
    },

    setAutoPlay(){
        let list = [];
        for (let i = 1; i < 9; i++) {
            let item = cc.find("item_" + i, this.node);
            if(this._haveOpenReward.indexOf(i) != 0){
                list.push(i)
            }
        }

        let randomIdx = Global.random(0,list.length-1)
        let self = this;
        cc.vv.gameData.checkAutoPlay( cc.find("item_" + list[randomIdx], this.node), function (){self.onClickItem(list[randomIdx])});
    },

    reset() {
        this._haveOpenReward = [];
        this._result = null;
        this._index = 1;
        this._canSelect = true;
        this._unlockBooster = [];
    },

    async onRcvSubGameData(msg) {
        if (msg.code !== 200) {
            this._canSelect = true;
            return;
        }

        let cfg = cc.vv.gameData.getGameCfg();
        let data = msg.data;
        this._result = data;
        this._haveOpenReward.push(data.choiceId);
        if (data.choiceItem.type !== cfg.MapBoostType.Coin) {
            this._unlockBooster.push(data.choiceItem.type);
        }
        if (data.pickBoosterGame.isEnd) {
            // 结束了
            let item = this.items[data.choiceId - 1];
            this.showReward(item, false, data.choiceItem);

            await cc.vv.gameData.awaitTime(0.8);

            cc.vv.AudioManager.playEff("games/VampireCount/", "pick_end", true);

            let resultIndex = 0;
            for (let i = 0; i < this.items.length; i++) {
                if (this._haveOpenReward.indexOf(i + 1) === -1) {
                    let item = this.items[i];
                    this.showReward(item, true, data.pickBoosterGame.totalItems[resultIndex]);
                    resultIndex++;
                }
            }

            // this.role.setAnimation(0, "animation2", false);

            await cc.vv.gameData.awaitTime(2);

            await this.popResult();

            this._successCallback();
        } else {
            // 没结束
            this._canSelect = true;
            let item = this.items[data.choiceId - 1];
            this.showReward(item, false, data.choiceItem);
            this.setAutoPlay();
        }
    },

    getResult() {
        return this._result;
    },

    async showReward(item, isGray, reward) {
        let cfg = cc.vv.gameData.getGameCfg();
        let spine = item.getChildByName("spine").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation" + this._index + "_2");
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
        });

        if (!isGray) {
            if (reward.type === cfg.MapBoostType.Coin) {
                cc.vv.AudioManager.playEff("games/VampireCount/", "pick_coin", true);
            } else {
                cc.vv.AudioManager.playEff("games/VampireCount/", "pick_booster", true);
            }
        }

        await cc.vv.gameData.awaitTime(0.8);

        let result_node = cc.find("result_" + reward.type, item);
        if (result_node) {
            result_node.active = true;
            result_node.scale = 2.1;
            result_node.color = isGray ? cc.Color.GRAY : cc.Color.WHITE;
            for (let child of result_node.children) {
                child.color = isGray ? cc.Color.GRAY : cc.Color.WHITE;
            }
            if (reward.type === cfg.MapBoostType.Coin) {
                cc.find("coin", result_node).getComponent(cc.Label).string = Global.formatNumShort(reward.coin, 0);
            }

            cc.tween(result_node)
                .to(0.5, {scale: 2}, {easing: "backOut"})
                .start();
        }
    },

    async popResult() {
        return new Promise((success)=>{
            let cfg = cc.vv.gameData.getGameCfg();
            if (this._result) {
                let boosterNum = 0;
                for (let item of this._result.pickBoosterGame.choiceItems) {
                    if (item.type !== cfg.MapBoostType.Coin) {
                        boosterNum++;
                    }
                }

                cc.vv.AudioManager.playEff("games/VampireCount/", "pick_end_show", true);

                let animationIndex = [2, 1, 3];
                this.black_bg.active = true;
                let node = cc.find("booster_result_" + boosterNum, this.node);
                node.active = true;
                let spine = node.getComponent(sp.Skeleton);
                spine.setAnimation(0, "animation" + animationIndex[boosterNum], false);
                spine.addAnimation(0, "animation" + animationIndex[boosterNum] + "_1", true);

                let coin = cc.find("coin", node);
                coin.scale = 0;
                Global.doRoallNumEff(coin, 0, this._result.pickBoosterGame.winCoin, 1.5, null, null, 0, true);
                cc.tween(coin)
                    .delay(0.2)
                    .to(0.5, {scale: 1}, {easing: "backOut"})
                    .start();

                let btn_collect = cc.find("btn_collect", node);
                btn_collect.scale = 0;
                cc.tween(btn_collect)
                    .delay(0.4)
                    .to(0.5, {scale: 1}, {easing: "backOut"})
                    .start();

                let booster_1 = cc.find("booster_1", node);
                if (booster_1) {
                    booster_1.scale = 0;
                    let atlas = cc.vv.gameData.GetAtlasByName("popup");
                    booster_1.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme214_pop_booster" + this._unlockBooster[0]);
                    cc.tween(booster_1)
                        .delay(0.3)
                        .to(0.5, {scale: boosterNum === 1 ? 1 : 0.8}, {easing: "backOut"})
                        .start();
                }

                let booster_2 = cc.find("booster_2", node);
                if (booster_2) {
                    let atlas = cc.vv.gameData.GetAtlasByName("popup");
                    booster_1.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme214_pop_booster" + this._unlockBooster[1]);
                    booster_2.scale = 0;
                    cc.tween(booster_2)
                        .delay(0.3)
                        .to(0.5, {scale: boosterNum === 1 ? 1 : 0.8}, {easing: "backOut"})
                        .start();
                }

                let index_1 = cc.find("index_1", node);
                if (index_1) {
                    index_1.scale = 0;
                    cc.tween(index_1)
                        .delay(0.3)
                        .to(0.5, {scale: 0.8}, {easing: "backOut"})
                        .start();
                }

                let index_2 = cc.find("index_2", node);
                if (index_2) {
                    index_2.scale = 0;
                    cc.tween(index_2)
                        .delay(0.3)
                        .to(0.5, {scale: 0.8}, {easing: "backOut"})
                        .start();
                }

                let func = ()=>{
                    cc.vv.AudioManager.playEff("games/VampireCount/", "click", true);

                    cc.vv.gameData.GetSlotsScript()._bottomScript.SetWin(this._result.pickBoosterGame.winCoin);

                    btn_collect.off("click");
                    cc.tween(coin)
                        .to(0.5, {scale: 0}, {easing: "backIn"})
                        .start();

                    cc.tween(btn_collect)
                        .to(0.5, {scale: 0}, {easing: "backIn"})
                        .start();

                    if (booster_1) {
                        cc.tween(booster_1)
                            .to(0.5, {scale: 0}, {easing: "backOut"})
                            .start();
                    }

                    if (booster_2) {
                        cc.tween(booster_2)
                            .to(0.5, {scale: 0}, {easing: "backOut"})
                            .start();
                    }

                    if (index_1) {
                        cc.tween(index_1)
                            .to(0.5, {scale: 0}, {easing: "backOut"})
                            .start();
                    }

                    if (index_2) {
                        cc.tween(index_2)
                            .to(0.5, {scale: 0}, {easing: "backOut"})
                            .start();
                    }

                    spine.setAnimation(0, "animation" + animationIndex[boosterNum] + "_2", false);
                    spine.setCompleteListener(()=>{
                        spine.setCompleteListener(null);
                        this.black_bg.active = false;
                        node.active = false;
                        success();
                    })
                }

                cc.vv.gameData.checkAutoPlay(btn_collect, func);

                btn_collect.on("click", ()=>{
                    btn_collect.stopAllActions();
                    func();
                });
            }
        });
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameData, false, this);
    },
});