/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_PrizePool_Base"),
    properties: {
        gray_font: cc.Font,
        yellow_font: cc.Font
    },

    ShowNodeLockByNode:function(node,bLock,unLockBet,poolType,bInit) {
        if (node) {
            let lockNode = cc.find("lock", node);
            let lockTips = cc.find("image", lockNode);
            let unlockNode = cc.find("unlock", node);
            let unlockTips = cc.find("image", unlockNode);
            let spine = cc.find("jp_suo", node).getComponent(sp.Skeleton);
            let text = cc.find("lbl_num", node).getComponent(cc.Label);
            if (bLock) {
                text.font = this.gray_font;
                if (bInit) {
                    lockNode.active = true;
                    unlockNode.active = false;
                    lockTips.scale = 0;
                } else {
                    cc.vv.AudioManager.playEff("games/VampireCount/", "jp_lock", true);
                    spine.clearTracks();
                    spine.setToSetupPose();
                    spine.setAnimation(0, "animation" + (4 - poolType) + "_2", false);

                    lockNode.active = true;
                    unlockNode.active = false;
                    lockTips.scale = 0;
                    cc.tween(lockTips)
                        .to(0.1, {scale: 0.7}, {easing: "backOut"})
                        .delay(2)
                        .to(0.1, {scale: 0}, {easing: "backIn"})
                        .start();
                }
            } else {
                text.font = this.yellow_font;
                if (bInit) {
                    lockNode.active = false;
                    unlockNode.active = true;
                    unlockTips.scale = 0;
                } else {
                    cc.vv.AudioManager.playEff("games/VampireCount/", "jp_unlock", true);
                    spine.clearTracks();
                    spine.setToSetupPose();
                    spine.setAnimation(0, "animation" + (4 - poolType) + "_1", false);

                    lockNode.active = false;
                    unlockNode.active = true;
                    unlockTips.scale = 0;
                    cc.tween(unlockTips)
                        .to(0.1, {scale: 0.7}, {easing: "backOut"})
                        .delay(2)
                        .to(0.1, {scale: 0}, {easing: "backIn"})
                        .start();
                }
            }
        }
    },
});